def kernel_gramschmidt_base(
    m: size,
    n: size,
    A: DATA_TYPE[m, n] @ DRAM,
    R: DATA_TYPE[n, n] @ DRAM,
    Q: DATA_TYPE[m, n] @ DRAM,
):
    # Simple sanity assertions on problem sizes.
    assert m > 0
    assert n > 0

    nrm: DATA_TYPE

    for k in seq(0, n):
        # nrm = sum_{i=0}^{m-1} A[i, k]^2
        nrm = 0.0
        for i in seq(0, m):
            nrm += A[i, k] * A[i, k]

