        for i in seq(0, m):
            Q[i, k] = A[i, k] / R[k, k]

        # For each j > k, update R[k, j] and A[:, j]
        #
        # The baseline structure is:
        #   for j in seq(k + 1, n):
        #       R[k, j] = 0.0
        #       for i in seq(0, m):
        #           R[k, j] += Q[i, k] * A[i, j]
        #       for i in seq(0, m):
        #           A[i, j] = A[i, j] - Q[i, k] * R[k, j]
        #
        # This iterates down columns of A and R (strided in memory).
        # We will later restructure these loops using scheduling so that
        # the j-dimension (columns) becomes the innermost loop, improving
        # spatial locality for both A and R.
        for j in seq(k + 1, n):
            # Initialize R[k, j]
            R[k, j] = 0.0

            # Accumulate R[k, j] = Q[:, k]^T * A[:, j]
            for i in seq(0, m):
                R[k, j] += Q[i, k] * A[i, j]

            # Update A[:, j] = A[:, j] - Q[:, k] * R[k, j]
            for i in seq(0, m):
                A[i, j] = A[i, j] - Q[i, k] * R[k, j]


